fn wait_for_code(listener: &TcpListener, expected_state: &str) -> Result<String, String> { listener .set_nonblocking(true) .map_err(|e| e.to_string())?; let deadline = Instant::now() + Duration::from_secs(180); loop { if Instant::now() > deadline { return Err("authorization timed out".into()); } match listener.accept() { Ok((mut stream, _)) => { let mut buf = [0u8; 4096]; let n = stream.read(&mut buf).unwrap_or(0); let req = String::from_utf8_lossy(&buf[..n]); let line = req.lines().next().unwrap_or(""); let path = line.split_whitespace().nth(1).unwrap_or(""); let query = path.split('?').nth(1).unwrap_or(""); let (mut code, mut state, mut err) = (None, None, None); for pair in query.split('&') { let mut kv = pair.splitn(2, '='); let k = kv.next().unwrap_or(""); let v = kv.next().unwrap_or(""); match k { "code" => code = Some(percent_decode(v)), "state" => state = Some(percent_decode(v)), "error" => err = Some(percent_decode(v)), _ => {} } } let ok = err.is_none() && code.is_some(); let body = if ok { "<!doctype html><meta charset=utf-8><body style="font-family:-apple-system,\ sans-serif;background:#0a0a0c;color:#eceef2;display:grid;place-items:center;\ height:100vh;margin:0"><div><h2>HypeMuzik connected ✓</h2><p>You can close \ this tab and return to the app.</p></div>" } else { "<!doctype html><meta charset=utf-8><body style="font-family:sans-serif;\ background:#0a0a0c;color:#eceef2"><h2>Sign-in failed</h2>" }; let resp = format!( "HTTP/1.1 200 OK
Content-Type: text/html; charset=utf-8
Content-Length: \ {}
Connection: close

{}", body.len(), body ); let _ = stream.write_all(resp.as_bytes()); if let Some(e) = err { return Err(format!("authorization denied: {e}")); } if state.as_deref() != Some(expected_state) { return Err("state mismatch (possible CSRF)".into()); } return code.ok_or_else(|| "no authorization code returned".into()); } Err(ref e) if e.kind() == std::io::ErrorKind::WouldBlock => { std::thread::sleep(Duration::from_millis(120)); } Err(e) => return Err(e.to_string()), } } }

fn the_proxy_streams_a_whole_video_in_bounded_chunks() { use std::io::{BufRead, BufReader, Read, Write}; // 3.5 chunks of body, so the walk takes several requests and a short tail. let total: usize = (VIDEO_CHUNK as usize) * 3 + 512; let body: Vec<u8> = (0..total).map(|i| (i % 251) as u8).collect(); let body_for_server = body.clone(); let upstream = std::net::TcpListener::bind("127.0.0.1:0").unwrap(); let upstream_port = upstream.local_addr().unwrap().port(); let server = std::thread::spawn(move || { let mut max_seen: u64 = 0; // The proxy fetches clen from the url, so there's no probe — one // connection per chunk (Connection: close each time). loop { let Ok((mut sock, _)) = upstream.accept() else { break }; let mut reader = BufReader::new(sock.try_clone().unwrap()); let mut range = String::new(); loop { let mut line = String::new(); if reader.read_line(&mut line).unwrap() == 0 || line == "
" { break; } if line.to_ascii_lowercase().starts_with("range:") { range = line.trim().to_string(); } } // Parse "Range: bytes=lo-hi". let spec = range.split_once("bytes=").map(|(_, r)| r.trim().to_string()).unwrap_or_default(); let (lo, hi) = spec.split_once('-').unwrap_or(("", "")); let lo: u64 = lo.trim().parse().unwrap_or(0); let hi_opt: Option<u64> = hi.trim().parse().ok(); // Reject exactly what real googlevideo rejects: open-ended, or a // span bigger than one chunk. let too_big = match hi_opt { None => true, Some(hi) => hi.saturating_sub(lo) + 1 > VIDEO_CHUNK, }; if too_big { sock.write_all(b"HTTP/1.1 403 Forbidden
Content-Length: 0
Connection: close

").unwrap(); sock.flush().unwrap(); continue; } let hi = hi_opt.unwrap().min(total as u64 - 1); max_seen = max_seen.max(hi - lo + 1); let slice = &body_for_server[lo as usize..=hi as usize]; let header = format!( "HTTP/1.1 206 Partial Content
Content-Type: video/mp4
Content-Range: bytes {lo}-{hi}/{total}
Content-Length: {}
Connection: close

", slice.len() ); sock.write_all(header.as_bytes()).unwrap(); sock.write_all(slice).unwrap(); sock.flush().unwrap(); if hi as usize + 1 >= total { return max_seen; } } max_seen }); let proxy = start().expect("proxy starts"); let target = format!("http://127.0.0.1:{upstream_port}/videoplayback?clen={total}"); let resp = reqwest::blocking::Client::new() .get(proxy.video_url(&target, None)) .send() .expect("proxy answers"); assert_eq!(resp.status().as_u16(), 200, "no element range ⇒ 200 over the whole file"); let mut got = Vec::new(); resp.take(total as u64 + 1024).read_to_end(&mut got).unwrap(); assert_eq!(got.len(), total, "the proxy must deliver every byte"); assert_eq!(got, body, "and the bytes must be the file, in order"); let max_chunk = server.join().unwrap(); assert!( max_chunk <= VIDEO_CHUNK, "the proxy asked for {max_chunk} bytes at once — googlevideo would 403 that" ); }

